function sumEven(limit) {
  let total = 0;
  for (let number = 1; number <= limit; number += 1) {
    if (number % 2 !== 0) continue;
    total += number;
  }
  return total;
}

function sumMultiplesOfFive(limit) {
  let total = 0;
  for (let number = 1; number <= limit; number += 1) {
    if (number % 5 === 0) total += number;
  }
  return total;
}

function sumExcept(limit, excluded) {
  let total = 0;
  for (let number = 1; number <= limit; number += 1) {
    if (number === excluded) continue;
    total += number;
  }
  return total;
}
